from pathlib import Path
p=Path('rag/service/baidu_maps.py');s=p.read_text(encoding='utf-8');s=s.replace('def __init__(self,key=None,session=None,timeout=10):','def __init__(self,key=None,session=None,timeout=10,budget=True):').replace('self.key=key or api_key();self.session=session or requests.Session();self.timeout=timeout','self.key=key or api_key();self.session=session or requests.Session();self.timeout=timeout\n        self.budget=budget;self.cache_info=None')
s=s.replace('    def get(self,path,params):','    def get(self,path,params):\n        if not self.key:raise MapError("missing_baidu_key","not_queried")\n        if not self.budget:return self._get(path,params)\n        from service.map_budget import MapBudget,BudgetDenied\n        try:\n            data,at,hit=MapBudget().fetch(path,params,lambda:self._get(path,params))\n            self.cache_info={"cache_hit":hit,"fetched_at":datetime.fromtimestamp(at,CN).isoformat(timespec="seconds")}\n            return data\n        except BudgetDenied as e:raise MapError(str(e),"not_queried") from None\n        except (OSError, __import__("sqlite3").Error):raise MapError("budget_store_unavailable","not_queried") from None\n\n    def _get(self,path,params):')
s=s.replace("        body=SCHEMAS[action].model_validate(args)","        self.cache_info=None\n        body=SCHEMAS[action].model_validate(args)").replace("return {**metadata,'state':'queried_with_evidence',**data}","return {**metadata,'state':'queried_with_evidence',**data,**(self.cache_info or {})}")
p.write_text(s,encoding='utf-8')
